// Funzione per formattare data e ora in DD-MM-YYYY e HH:MM
function formatDateTime(date) {
    const day   = String(date.getDate()).padStart(2, "0");
    const month = String(date.getMonth() + 1).padStart(2, "0");
    const year  = date.getFullYear();

    const hours   = String(date.getHours()).padStart(2, "0");
    const minutes = String(date.getMinutes()).padStart(2, "0");

    return {
        formattedDate: `${day}-${month}-${year}`,   // 16-12-2025
        formattedTime: `${hours}:${minutes}`        // HH:MM
    };
}

// Data attuale
const currentDate = new Date();

// Data e ora di oggi
const { formattedDate: date, formattedTime: time } = formatDateTime(currentDate);

// Data di domani
const tomorrow = new Date(currentDate);
tomorrow.setDate(currentDate.getDate() + 1);
const { formattedDate: domani } = formatDateTime(tomorrow);

// URL per ottenere gli eventi di oggi
msg.url = `https://services.tivulaguida.it/api/epg/programming/events/next/${date}`;

// Data e ora dell'ultimo controllo
const lastCheckedDate = new Date(msg.timestamp || Date.now());
const { formattedDate: date2, formattedTime: time2 } = formatDateTime(lastCheckedDate);

// Timestamp finale
msg.timestamp = `${time2} ${date2}`;

return msg;

const resultLength = msg.payload.events.length;

for (let i = 0; i < resultLength; i++) {
    let attrName = msg.payload.events[i].channel.name;
    msg[attrName] = msg.payload.events[i];

}

node.send(msg);

return;

